shortcuts.codeOnPrepare:
const shared = getVariable('text_payload');
if (!shared || shared.trim() === '') {
  setVariable('text_payload', getClipboardContent() || '');
}

shortcuts.codeOnSuccess:
const data = JSON.parse(response.body);
if (data.type === 'text') {
  copyToClipboard(data.content);
  showToast('Copied PC text to phone clipboard!');
} else if (data.type === 'image') {
  openUrl('http://' + getVariable('pc_ip') + ':5050/?key=' + getVariable('secret_key') + '&action=pull');
} else if (data.type === 'files') {
  if (data.files.length === 1) {
    openUrl('http://' + getVariable('pc_ip') + ':5050' + data.files[0].url);
  } else {
    openUrl('http://' + getVariable('pc_ip') + ':5050/?key=' + getVariable('secret_key') + '&action=pull');
  }
} else {
  showToast('Windows clipboard is empty');
}
